with base as (select *, length(supplier_name) as supplier_name_length, coalesce(city, 'N/A') as resolved_city from suppliers where supplier_name is not null) select id, supplier_name, country, city, rating, supplier_name_length, resolved_city, lag(rating, 1) over (partition by city order by rating, id) as prev_rating, percent_rank() over (partition by country, city order by supplier_name_length nulls last) as supplier_name_length_percent_rank, ntile(4) over (partition by country, city order by rating, id) as rating_bucket from base
